<script setup lang="ts">
import { computed, onMounted, ref } from 'vue'

type Project = { id: string; name: string; taskCount: number; progress: number; overdueTaskCount: number; role: 'owner' | 'editor' | 'reader'; updatedAt?: string }
type Invitation = { id: string; project_id: string; project_name: string; role: 'editor' | 'reader' }
const props = defineProps<{ opening: boolean; openError: string }>()
const emit = defineEmits<{ open: [id: string] }>()
const projects = ref<Project[]>([]), invitations = ref<Invitation[]>([]), loading = ref(true), listingError = ref(''), createDialog = ref(false), name = ref(''), creating = ref(false), accepting = ref<string | null>(null), openingId = ref<string | null>(null)
const error = computed(() => listingError.value || props.openError)
const csrfHeaders = (): Record<string, string> => { const token = document.querySelector<HTMLMetaElement>('meta[name="csrf-token"]')?.content; return token ? { 'X-CSRF-TOKEN': token } : {} }
const roleLabel = (role: Project['role'] | Invitation['role']) => role === 'owner' ? 'Proprietário' : role === 'editor' ? 'Editor' : 'Leitor'
const taskLabel = (count: number) => `${count} ${count === 1 ? 'tarefa' : 'tarefas'}`
async function load() { loading.value = true; listingError.value = ''; try { const [projectResponse, invitationResponse] = await Promise.all([fetch('/api/v1/projects'), fetch('/api/v1/invitations')]); if (!projectResponse.ok || !invitationResponse.ok) throw new Error('Não foi possível carregar os projetos.'); projects.value = (await projectResponse.json()).data; invitations.value = (await invitationResponse.json()).data } catch (exception) { listingError.value = exception instanceof Error ? exception.message : 'Erro inesperado.' } finally { loading.value = false } }
function open(projectId: string) { if (props.opening) return; openingId.value = projectId; emit('open', projectId) }
function closeCreateDialog() { if (creating.value) return; createDialog.value = false; name.value = '' }
async function create() { if (!name.value.trim() || creating.value) return; creating.value = true; listingError.value = ''; try { const response = await fetch('/api/v1/projects', { method: 'POST', headers: { 'Content-Type': 'application/json', Accept: 'application/json', ...csrfHeaders() }, body: JSON.stringify({ name: name.value.trim(), commandId: crypto.randomUUID() }) }); if (!response.ok) throw new Error('Não foi possível criar o projeto.'); const project = (await response.json()).data; createDialog.value = false; name.value = ''; open(project.id) } catch (exception) { listingError.value = exception instanceof Error ? exception.message : 'Erro inesperado.' } finally { creating.value = false } }
async function accept(invitation: Invitation) { accepting.value = invitation.id; listingError.value = ''; try { const response = await fetch(`/api/v1/invitations/${invitation.id}/accept`, { method: 'POST', headers: { Accept: 'application/json', ...csrfHeaders() } }); if (!response.ok) throw new Error('Não foi possível aceitar o convite.'); open((await response.json()).data.projectId) } catch (exception) { listingError.value = exception instanceof Error ? exception.message : 'Erro inesperado.' } finally { accepting.value = null } }
onMounted(load)
</script>

<template>
  <main class="project-dashboard">
    <header class="dashboard-header"><div><span class="eyebrow">ESPAÇO DE TRABALHO</span><h1>Seus projetos</h1><p>Escolha um projeto para continuar o planejamento.</p></div><button class="primary new-project" @click="createDialog = true"><span>+</span>Novo Projeto</button></header>
    <p v-if="error" class="dashboard-error" role="alert">{{ error }} <button class="soft-btn" :disabled="loading || opening" @click="load">Tentar novamente</button></p>
    <section v-if="loading" class="project-skeletons" aria-label="Carregando projetos"><i v-for="index in 3" :key="index"></i></section>
    <template v-else>
      <section v-if="invitations.length" class="invitation-section"><header><span class="eyebrow">CONVITES</span><h2>Projetos compartilhados com você</h2></header><article v-for="invitation in invitations" :key="invitation.id" class="invitation-card"><span class="invite-icon">↗</span><div><b>{{ invitation.project_name }}</b><small>Acesso de {{ roleLabel(invitation.role).toLocaleLowerCase('pt-BR') }}</small></div><button class="soft-btn" :disabled="accepting === invitation.id || opening" @click="accept(invitation)">{{ accepting === invitation.id ? 'Aceitando…' : 'Aceitar convite' }}</button></article></section>
      <section class="project-section"><header><div><span class="eyebrow">PROJETOS</span><h2>{{ projects.length ? 'Continue de onde parou' : 'Seu espaço está pronto' }}</h2></div><small v-if="projects.length">{{ projects.length }} {{ projects.length === 1 ? 'projeto' : 'projetos' }}</small></header><div v-if="projects.length" class="project-grid"><button v-for="project in projects" :key="project.id" class="project-card" :class="{ opening: opening && openingId === project.id }" :disabled="opening" @click="open(project.id)"><div class="project-card-head"><span class="project-mark">{{ project.name.slice(0, 1).toUpperCase() }}</span><span class="project-role">{{ roleLabel(project.role) }}</span></div><b>{{ project.name }}</b><small>{{ taskLabel(project.taskCount) }}</small><div class="project-progress"><span><i :style="{ width: `${project.progress}%` }"></i></span><strong>{{ project.progress }}%</strong></div><footer><span :class="{ risk: project.overdueTaskCount }">{{ project.overdueTaskCount ? `${project.overdueTaskCount} atrasada(s)` : 'Sem atrasos' }}</span><em>{{ opening && openingId === project.id ? 'Abrindo projeto…' : 'Abrir →' }}</em></footer></button></div><section v-else class="empty-projects"><span>✦</span><h3>Crie seu primeiro projeto</h3><p>Organize tarefas, responsáveis e o seu planejamento em um único lugar.</p><button class="primary" @click="createDialog = true"><b>+</b>Novo Projeto</button></section></section>
    </template>
    <Teleport to="body"><div v-if="createDialog" class="project-dialog-scrim" @click.self="closeCreateDialog"><form class="project-dialog" role="dialog" aria-modal="true" aria-labelledby="new-project-title" @submit.prevent="create" @keydown.esc="closeCreateDialog"><header><div><span class="eyebrow">NOVO PROJETO</span><h2 id="new-project-title">Dê um nome ao seu planejamento</h2></div><button type="button" class="drawer-close" aria-label="Fechar" @click="closeCreateDialog">×</button></header><label>Nome do projeto<input v-model="name" autofocus maxlength="255" placeholder="Ex.: Lançamento do produto" @keydown.enter.prevent="create"></label><p>Você poderá organizar seções, tarefas, responsáveis e dependências em seguida.</p><footer><button type="button" class="soft-btn" :disabled="creating" @click="closeCreateDialog">Cancelar</button><button class="primary" :disabled="creating || !name.trim()">{{ creating ? 'Criando…' : 'Criar projeto' }}</button></footer></form></div></Teleport>
  </main>
</template>

<style scoped>
